import{_ as e,o as d,c as o,ao as r}from"./chunks/framework.Crdx-bjS.js";const y=JSON.parse('{"title":"Model parameters","description":"","frontmatter":{},"headers":[],"relativePath":"parameters.md","filePath":"parameters.md","lastUpdated":null}'),i={name:"parameters.md"};function n(a,t,s,c,l,g){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="Model-parameters" tabindex="-1">Model parameters <a class="header-anchor" href="#Model-parameters" aria-label="Permalink to &quot;Model parameters {#Model-parameters}&quot;">​</a></h1><p>Every option is set through <a href="/GEMB.jl/previews/PR90/api#GEMB.initialize_parameters"><code>initialize_parameters</code></a>, which validates each value at construction. <strong>Defaults are in bold.</strong> Physics defaults follow the two firn-model intercomparisons — RetMIP (Vandecrux et al., 2020) and FirnMICE (Lundin et al., 2017) — and, where those are silent, the shipped configurations of the <a href="https://github.com/UWGlaciology/CommunityFirnModel" target="_blank" rel="noreferrer">Community Firn Model</a> and <a href="https://github.com/IMAU-ice-and-climate/IMAU-FDM" target="_blank" rel="noreferrer">IMAU-FDM</a>. Each option&#39;s full citation and rationale is in the <a href="/GEMB.jl/previews/PR90/api#GEMB.ModelParameters"><code>ModelParameters</code></a> docstring. The exception is the snow set: fresh-snow density, settling and grain growth default to one configuration calibrated together on SNOTEL seasonal snow (<code>new_snow_method = :vanKampenhout2017SNOTEL</code>, <code>densification_method = :Crocus</code> with destructive metamorphism at <code>destructive_metamorphism_density = 100</code>, and <code>grain_growth_method = :FlannerZender2006</code>). <code>:vanKampenhout2017SNOTEL</code> deposits light snow that only <code>:Crocus</code> settling with destructive metamorphism at that density compacts at the observed rate, so changing one member alone leaves the others outside the regime they were fitted in: change them together. Choosing another <code>densification_method</code> turns destructive metamorphism off. The Community Firn Model&#39;s configuration is <code>new_snow_method = :Constant350</code>, <code>densification_method = :Arthern</code> and <code>grain_growth_method = :hybrid</code>, without destructive metamorphism. The calibration is described under Fresh snow on the Physics Notes page.</p><h2 id="Method-options" tabindex="-1">Method options <a class="header-anchor" href="#Method-options" aria-label="Permalink to &quot;Method options {#Method-options}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Options</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>densification_method</code></td><td style="text-align:right;"><code>:Arthern</code>, <code>:ArthernB</code>, <code>:HerronLangway</code>, <code>:Barnola1991</code>, <strong><code>:Crocus</code></strong>, <code>:CrocusPure</code>, <code>:GSFC2020</code>, <code>:Simonsen2013</code>, <code>:Ligtenberg</code></td><td style="text-align:right;">Firn compaction law. FirnMICE finds the raw <code>:Arthern</code> (k₀=k₁=1) the most accumulation-sensitive of the eight schemes tested; <code>:Ligtenberg</code> and <code>:GSFC2020</code> are its recalibrated successors and are worth considering for a specific domain</td></tr><tr><td style="text-align:right;"><code>crocus_handoff_law</code></td><td style="text-align:right;"><strong><code>:Arthern</code></strong>, <code>:GSFC2020</code></td><td style="text-align:right;">The accumulation-driven law <code>:Crocus</code> hands firn to</td></tr><tr><td style="text-align:right;"><code>crocus_handoff_rule</code></td><td style="text-align:right;"><code>:density</code>, <strong><code>:rate_match</code></strong></td><td style="text-align:right;"><code>:density</code> switches every cell at or above <code>crocus_handoff_density</code>; <code>:rate_match</code> gives such a cell the faster of the two laws, so the switch falls where their rates cross. Both handoff settings are rejected with any other <code>densification_method</code> unless left at their defaults</td></tr><tr><td style="text-align:right;"><code>densification_accumulation</code></td><td style="text-align:right;"><strong><code>:accumulation</code></strong>, <code>:precipitation</code></td><td style="text-align:right;">Whether compaction is driven by mean snowfall or by mean total precipitation</td></tr><tr><td style="text-align:right;"><code>thermal_conductivity_method</code></td><td style="text-align:right;"><strong><code>:Calonne2019Air</code></strong>, <code>:Calonne2019</code>, <code>:Calonne</code>, <code>:Sturm</code>, <code>:Marchenko2019</code></td><td style="text-align:right;">RetMIP §5.1 recommends Calonne et al. (2019) by name; the CFM and IMAU-FDM both ship it. <code>:Calonne2019Air</code> is eq. 5 as published, with the air-conductivity ratio on the snow branch, as IMAU-FDM carries it; <code>:Calonne2019</code> omits that ratio, as the CFM does</td></tr><tr><td style="text-align:right;"><code>thermal_solver</code></td><td style="text-align:right;"><strong><code>ExplicitThermal()</code></strong>, <code>ImplicitThermal()</code></td><td style="text-align:right;">Thermal integration scheme, selected by <em>type</em> rather than by <code>Symbol</code>. <code>ExplicitThermal</code> sub-steps to the Von Neumann stability limit, so its cost is set by the stiffest cell; <code>ImplicitThermal</code> is backward Euler on a tridiagonal system, unconditionally stable, and sub-steps only for accuracy. The explicit default is faster on a well-conditioned column (measured 2.4 s vs 5.8 s over a year of 3-hourly forcing) and is what the implicit path is validated against; the implicit path is the robust choice when thin refrozen lenses collapse the stability limit</td></tr><tr><td style="text-align:right;"><code>thermal_explicit_safety_factor</code></td><td style="text-align:right;"><strong><code>0.8</code></strong>, any value in (0, 1]</td><td style="text-align:right;">Fraction of the diffusive stability limit <code>ExplicitThermal</code> may sub-step at; unread by <code>ImplicitThermal</code>. Not slack against an imprecise limit: <code>_max_safe_dt</code> bounds diffusion only, while the surface cell also carries the surface energy balance&#39;s feedback <code>Λ = dQ/dT₁ ≤ 0</code> in the same coefficient, and nothing in the model bounds <code>Λ</code>. Over a year of 3-hourly forcing at the synthetic site the realized surface amplification factor stayed ≤ 0.955 at 0.8 but exceeded 1 on 0.65% of steps at 0.95, for ~17% fewer sub-steps. Raise it toward 1.0 to trade monotonicity margin for speed on a well-conditioned column; use <code>ImplicitThermal()</code> if the step limit should be gone rather than loosened</td></tr><tr><td style="text-align:right;"><code>heat_capacity_method</code></td><td style="text-align:right;"><strong><code>:CuffeyPaterson</code></strong>, <code>:constant</code></td><td style="text-align:right;"><code>:CuffeyPaterson</code> is <code>152.5 + 7.122·T</code> (Cuffey &amp; Paterson 2010 eq. 9.1, p. 400); <code>:constant</code> (<code>heat_capacity_ice</code>, 2102 J kg⁻¹ K⁻¹) matches the CFM&#39;s melt-enabled path</td></tr><tr><td style="text-align:right;"><code>rain_heat_capacity</code></td><td style="text-align:right;"><strong><code>:water</code></strong>, <code>:ice</code></td><td style="text-align:right;">Heat capacity carrying rain&#39;s sensible heat above the melting point</td></tr><tr><td style="text-align:right;"><code>mean_temperature_method</code></td><td style="text-align:right;"><strong><code>:arithmetic</code></strong>, <code>:arrhenius</code></td><td style="text-align:right;">How the mean annual temperature driving densification is averaged</td></tr><tr><td style="text-align:right;"><code>grain_growth_method</code></td><td style="text-align:right;"><code>:hybrid</code>, <code>:Arthern</code>, <code>:Marbouty</code>, <code>:Taillandier2007</code>, <strong><code>:FlannerZender2006</code></strong></td><td style="text-align:right;">Dry non-dendritic grain growth. <code>:Marbouty</code> is temperature-gradient metamorphism, inactive above 400 kg m⁻³ and below 16 K m⁻¹; <code>:hybrid</code> runs it below 400 kg m⁻³ and <code>:Arthern</code> above. The CFM ships <code>:Arthern</code>. <code>:Taillandier2007</code> replaces Marbouty below 400 kg m⁻³ by measured dry-snow SSA decay (Taillandier et al., 2007, eqs. 9 and 13). <code>:FlannerZender2006</code> is the snow aging of SNICAR in CLM5.0 (Flanner and Zender, 2006; Flanner et al., 2007): the SNICAR table&#39;s dry law at each cell&#39;s temperature, gradient and density, CLM&#39;s wet growth and refrozen-water radius, for all snow below 400 kg m⁻³ and all dendritic snow, with radius as state of its own</td></tr><tr><td style="text-align:right;"><code>water_irreducible_method</code></td><td style="text-align:right;"><strong><code>:ColeouLesaffre</code></strong>, <code>:constant</code></td><td style="text-align:right;">Both the CFM and IMAU-FDM use Coléou &amp; Lesaffre. RetMIP §5.4 ties a flat saturation to under-retention in the percolation zone</td></tr><tr><td style="text-align:right;"><code>melt_geometry</code></td><td style="text-align:right;"><strong><code>:thickness</code></strong>, <code>:density</code></td><td style="text-align:right;">What melting does to a cell: shrink <code>dz</code> at fixed density (Crocus) or lower density at fixed <code>dz</code> (SNOWPACK). Only <code>:density</code> makes a melt–refreeze cycle return the geometry as well as the mass</td></tr><tr><td style="text-align:right;"><code>runoff_method</code></td><td style="text-align:right;"><strong><code>:instantaneous</code></strong>, <code>:ZuoOerlemans</code>, <code>:Darcy</code></td><td style="text-align:right;">All three RetMIP bucket lineages and both comparison models use instantaneous runoff. The other two give a drainage timescale and permit firn aquifers</td></tr><tr><td style="text-align:right;"><code>new_snow_method</code></td><td style="text-align:right;"><code>:Constant350</code>, <code>:Constant315</code>, <code>:Constant150</code>, <code>:Constant</code>, <code>:Fausto</code>, <code>:FaustoFit</code>, <code>:Pahaut</code>, <code>:Kaspers</code>, <code>:KuipersMunneke</code>, <code>:vanKampenhout2017</code>, <strong><code>:vanKampenhout2017SNOTEL</code></strong></td><td style="text-align:right;">Fresh-snow density. The CFM ships a constant 350. <code>:Constant*</code> are bare constants, <code>:Constant</code> at <code>new_snow_density</code> (50–550 kg m⁻³, default 350); <code>:Fausto</code>/<code>:FaustoFit</code>/<code>:Pahaut</code> also select the Crocus wind-dependent fresh-grain properties. <code>:Pahaut</code> is the only alpine-seasonal-snow fit — prefer it for temperate and mid-latitude glaciers, where the polar fits run too dense. <code>:vanKampenhout2017</code> is the CLM5 deposition density (temperature plus 10 m wind, van Kampenhout et al., 2017, eqs. 2–4); pair it with <code>densification_method = :Crocus</code> (destructive metamorphism is on by default there). <code>:vanKampenhout2017SNOTEL</code> is <code>:vanKampenhout2017</code> with a temperature term calibrated on SNOTEL snowfall days; see Fresh snow in the Physics Notes</td></tr><tr><td style="text-align:right;"><code>blowing_snow_method</code></td><td style="text-align:right;"><strong><code>:none</code></strong>, <code>:Crocus</code>, <code>:Keenan2021</code></td><td style="text-align:right;">Wind rework of snow already on the ground. <code>:Crocus</code> is the SURFEX/Crocus <code>SNOWDRIFT</code> scheme (Vionnet et al., 2012; Lafaysse et al., 2026 eqs. 59–66). Exactly mass-conserving on its own: it compacts and fragments, it does not erode. Set <code>blowing_snow_sublimation</code> for the one term that removes mass, or <code>drift_rate</code> for the prescribed path. <code>:Keenan2021</code> is the SNOWPACK erosion–redeposition scheme (Keenan et al., 2021, eqs. 3–4) with the Crocus mobility threshold; it replaces the <code>:Crocus</code> compaction and is also mass-conserving</td></tr><tr><td style="text-align:right;"><code>albedo_method</code></td><td style="text-align:right;"><strong><code>:GardnerSharp</code></strong>, <code>:BrunLefebre</code>, <code>:GreuellKonzelmann</code>, <code>:None</code></td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>emissivity_method</code></td><td style="text-align:right;"><strong><code>:uniform</code></strong>, <code>:grain_radius_threshold</code>, <code>:grain_radius_w_threshold</code></td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>initialize_age</code></td><td style="text-align:right;"><strong><code>:steady_state</code></strong>, <code>:zero</code></td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>output_frequency</code></td><td style="text-align:right;"><strong><code>:all</code></strong>, <code>:daily</code>, <code>:weekly</code>, <code>:monthly</code>, <code>:last</code></td><td style="text-align:right;"></td></tr></tbody></table><h2 id="Physical-and-numerical-settings" tabindex="-1">Physical and numerical settings <a class="header-anchor" href="#Physical-and-numerical-settings" aria-label="Permalink to &quot;Physical and numerical settings {#Physical-and-numerical-settings}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Default</th><th style="text-align:right;">Units</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>density_ice</code></td><td style="text-align:right;"><strong>917.0</strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;">Pure-ice density. Matches the CFM and IMAU-FDM, and the pure-ice density the Calonne (2019) conductivity and Barnola (1991) densification fits were built against</td></tr><tr><td style="text-align:right;"><code>water_irreducible_saturation</code></td><td style="text-align:right;"><strong>0.07</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Read only under <code>water_irreducible_method = :constant</code></td></tr><tr><td style="text-align:right;"><code>impermeable_density</code></td><td style="text-align:right;"><strong>830.0</strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;">Flow-blocking criterion; the same value the CFM uses. RetMIP models span 810–917</td></tr><tr><td style="text-align:right;"><code>impermeable_thickness</code></td><td style="text-align:right;"><strong>0.1</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Minimum blocking-lens thickness; the same value the CFM uses</td></tr><tr><td style="text-align:right;"><code>pore_saturation_max</code></td><td style="text-align:right;"><strong>1.0</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Cap on pore filling; only reachable when runoff is delayed</td></tr><tr><td style="text-align:right;"><code>heat_capacity_ice</code></td><td style="text-align:right;"><strong>2102.0</strong></td><td style="text-align:right;">J kg⁻¹ K⁻¹</td><td style="text-align:right;">Read only under <code>heat_capacity_method = :constant</code></td></tr><tr><td style="text-align:right;"><code>rain_temperature_threshold</code></td><td style="text-align:right;"><strong>273.15</strong></td><td style="text-align:right;">K</td><td style="text-align:right;">Rain/snow partition temperature</td></tr><tr><td style="text-align:right;"><code>emissivity</code></td><td style="text-align:right;"><strong>0.97</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>emissivity_grain_radius_large</code></td><td style="text-align:right;"><strong>0.97</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>emissivity_grain_radius_threshold</code></td><td style="text-align:right;"><strong>10.0</strong></td><td style="text-align:right;">mm</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>surface_roughness_effective_ratio</code></td><td style="text-align:right;"><strong>0.10</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>albedo_snow</code> / <code>albedo_ice</code> / <code>albedo_fixed</code></td><td style="text-align:right;"><strong>0.85</strong> / <strong>0.48</strong> / <strong>0.85</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>albedo_density_threshold</code></td><td style="text-align:right;"><strong><code>Inf</code></strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;"><code>Inf</code> disables the density-based snow/ice albedo switch</td></tr><tr><td style="text-align:right;"><code>cloud_fraction</code></td><td style="text-align:right;"><strong>0.1</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>shortwave_subsurface_absorption</code></td><td style="text-align:right;"><strong><code>false</code></strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Absorb shortwave with depth rather than at the surface only</td></tr><tr><td style="text-align:right;"><code>shortwave_downward_diffuse</code>, <code>solar_zenith_angle</code>, <code>cloud_optical_thickness</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">W m⁻², degrees, –</td><td style="text-align:right;">Used only where the forcing layer of the same name is identically zero</td></tr><tr><td style="text-align:right;"><code>black_carbon_snow</code>, <code>black_carbon_ice</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">ppmw</td><td style="text-align:right;">Applied to every step</td></tr><tr><td style="text-align:right;"><code>column_ztop</code></td><td style="text-align:right;"><strong>10.0</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Depth of the uniform near-surface zone</td></tr><tr><td style="text-align:right;"><code>column_dztop</code></td><td style="text-align:right;"><strong>0.05</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Cell thickness in that zone</td></tr><tr><td style="text-align:right;"><code>column_dzmin</code> / <code>column_dzmax</code></td><td style="text-align:right;"><strong>0.025</strong> / <strong>0.075</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Merge/split bands enforcing the fixed cell count</td></tr><tr><td style="text-align:right;"><code>column_depth_max</code></td><td style="text-align:right;"><strong>250.0</strong></td><td style="text-align:right;">m</td><td style="text-align:right;"><em>Ceiling</em> on the constructed column depth, not the depth itself</td></tr><tr><td style="text-align:right;"><code>column_zy</code></td><td style="text-align:right;"><strong>1.10</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Geometric growth ratio below <code>column_ztop</code></td></tr><tr><td style="text-align:right;"><code>destructive_metamorphism</code></td><td style="text-align:right;"><strong><code>true</code> under <code>:Crocus</code>/<code>:CrocusPure</code>, else <code>false</code></strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Add Anderson (1976) destructive-metamorphism settling (van Kampenhout et al., 2017, eq. 5; Schneider et al., 2022, eq. 3) to the <code>:Crocus</code>/<code>:CrocusPure</code> strain rate. Rejected with any other <code>densification_method</code></td></tr><tr><td style="text-align:right;"><code>destructive_metamorphism_density</code></td><td style="text-align:right;"><strong>100.0</strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;"><code>ρ_dm</code>, above which destructive metamorphism tapers by <code>exp(−0.046·(ρ − ρ_dm))</code>. Bounded to [50, 450]. 100 is the CLM4 value; CLM5 uses 175</td></tr><tr><td style="text-align:right;"><code>crocus_handoff_density</code></td><td style="text-align:right;"><strong>300.0</strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;">Density at or above which <code>:Crocus</code> hands a cell to <code>crocus_handoff_law</code>; under <code>crocus_handoff_rule = :rate_match</code>, the floor below which Crocus always governs. Bounded to [200, 830]. The Community Firn Model hands off at 450 under the <code>:density</code> rule (<code>CROCUS_HYBRID_DENSITY</code>)</td></tr><tr><td style="text-align:right;"><code>crocus_handoff_k0</code>, <code>crocus_handoff_k1</code></td><td style="text-align:right;"><strong>0.616702</strong>, <strong>0.665705</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Multipliers on the <code>:Crocus</code> handoff law&#39;s rate below / above <code>crocus_handoff_stage_density</code>. Bounded to (0, 10]</td></tr><tr><td style="text-align:right;"><code>crocus_handoff_activation_energy_shift</code></td><td style="text-align:right;"><strong>−9858.14</strong></td><td style="text-align:right;">J mol⁻¹</td><td style="text-align:right;">Added to the handoff law&#39;s creep activation energy; the rate is unchanged at 258.15 K (<code>CROCUS_HANDOFF_REFERENCE_TEMPERATURE</code>). Bounded to ±60000</td></tr><tr><td style="text-align:right;"><code>crocus_handoff_accumulation_exponent_scale</code></td><td style="text-align:right;"><strong>0.845621</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Multiplies the handoff law&#39;s accumulation exponent (1 for <code>:Arthern</code>, 0.91 / 0.644 for <code>:GSFC2020</code>); the rate is unchanged at 600 kg m⁻² yr⁻¹ (<code>CROCUS_HANDOFF_REFERENCE_ACCUMULATION</code>). Bounded to (0, 3]</td></tr><tr><td style="text-align:right;"><code>crocus_handoff_stage_density</code></td><td style="text-align:right;"><strong>545.319</strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;">The handoff law&#39;s stage-1/stage-2 transition. Bounded to [400, 830)</td></tr><tr><td style="text-align:right;"><code>crocus_overburden_factor</code></td><td style="text-align:right;"><strong>1.27096</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Multiplier on the <code>:Crocus</code> viscous strain rate, ramped linearly from 1 at 300 kg m⁻³ to its full value at 350. Bounded to (0, 10]. These six calibration factors are rejected with any other <code>densification_method</code> unless left at their defaults. The defaults of the handoff and its factors are <code>CROCUS_FIRN_CALIBRATION</code>, the firn-core calibration of the GEMB v2.0 paper; <code>ModelParameters(; CROCUS_PUBLISHED_HANDOFF...)</code> runs the published laws</td></tr><tr><td style="text-align:right;"><code>horizontal_strain_rate</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">yr⁻¹</td><td style="text-align:right;">Ice-dynamic layer thinning; 0 disables the term</td></tr><tr><td style="text-align:right;"><code>blowing_snow_sublimation</code></td><td style="text-align:right;"><strong><code>false</code></strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Whether <code>blowing_snow_method = :Crocus</code> also sublimates the suspended fraction (Gordon et al., 2006). Off is Crocus&#39;s own default (<code>OSNOWDRIFT_SUBLIM</code>), and it is the only part of the computed scheme that removes mass</td></tr><tr><td style="text-align:right;"><code>drift_fetch_length</code></td><td style="text-align:right;"><strong>10.0</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Fetch length <code>L</code> of the <code>:Keenan2021</code> saltation flux (Keenan et al., 2021, eq. 3); the reworked mass is inversely proportional to it. Bounded to (0, 1000]</td></tr><tr><td style="text-align:right;"><code>drift_rate</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">kg m⁻² yr⁻¹</td><td style="text-align:right;">Prescribed net drift divergence, positive for erosion; 0 disables the term. A constant-rate shorthand for the <code>snow_drift</code> forcing layer, which takes precedence when the forcing carries one. Bounded to ±2000</td></tr><tr><td style="text-align:right;"><code>surface_slope</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">m m⁻¹</td><td style="text-align:right;">Hydraulic gradient; read only under <code>:ZuoOerlemans</code>/<code>:Darcy</code></td></tr><tr><td style="text-align:right;"><code>output_viscosity</code></td><td style="text-align:right;"><strong><code>false</code></strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Adds a <code>viscosity</code> output layer; populated only under <code>:Crocus</code>/<code>:CrocusPure</code></td></tr></tbody></table>',6)])])}const m=e(i,[["render",n]]);export{y as __pageData,m as default};
